end



function IdolLive3D_LoaderV1.DeleteInstance()
    --printError("IdolLive3D_LoaderV1.DeleteInstance")
    if currentInstance ~= nil then 
        currentInstance:_ResetVCamBlendMode()
        currentInstance:Delete() -- 会调用 __delete()
        currentInstance = nil
    else 
        printError( "koko - 异常: IdolLive3D_LoaderV1 currentInstance 居然为 nil" )
    end 
end




