function IdolLive3D_LoaderV1:__delete()
    --printError("IdolLive3D_LoaderV1:__delete")
    for _,fx in pairs(self.allResources.fullScreenFXEnvs) do 
        if isNotNull(fx) then
            fx:Delete()
        end
    end 

    self.baseJson:Delete()

    IdolLive3D_Utils.StopCoroutine( self.co_1 )
    self.co_1 = nil

    IdolLive3D_Utils.ClearAllSceneNodes( false )
    --
    self:ReleaseAllLoader()
end





-- 第一批次, json 文件:
function IdolLive3D_LoaderV1:StartLoadJsonAsync( baseParamsJsonFilePath_, sceneParamsJsonFilePath_ )
    -- baseParams json: 
    self.baseParamsJsonLoader = ResourceModule.LoadBundleAsync(baseParamsJsonFilePath_, nil, true)
    self.sceneParamsJsonLoader = nil
    if isNotNull(sceneParamsJsonFilePath_) then 
        self.sceneParamsJsonLoader = ResourceModule.LoadBundleAsync(sceneParamsJsonFilePath_, nil, true)        
    end 
end


-- 第一批次, 各种资源:
function IdolLive3D_LoaderV1:StartLoadFirstBatchAsync( live3DCardVoRow_, isDemo_ )
    self.loaders = {}
    -- 角色:
    self.loaders["role"] = ResourceModule.LoadBundleAsync( IdolLive3D_Utils.GetRolePrefabPath(live3DCardVoRow_.skinId,isDemo_), nil, true)
    -- 场景:
    --self.loaders["builds"] = ResourceModule.LoadBundleAsync("Arts/Prefab_home/Prefab_runtime_item/DeepInteraction_Scene.prefab", nil, true)
    self.loaders["builds"] = ResourceModule.LoadBundleAsync(live3DCardVoRow_.scenePrefabPath, nil, true)
    -- 总处理器 prefab:
    self.loaders["runtime"] = ResourceModule.LoadBundleAsync("Prefabs/IdolLive3D/IdolLive3D_Runtime.prefab", nil, true)
end



-- 等待 json 文件加载完毕:
function IdolLive3D_LoaderV1:WaitJsonLoadingFinish()

    self.isTgtLoadDone = false
    for i=1,IdolLive3D_States.loadWaitFrames do 
        if      self.baseParamsJsonLoader.IsSuccess == true 
            and (self.sceneParamsJsonLoader==nil or self.sceneParamsJsonLoader.IsSuccess == true ) -- 允许不存在
        then 
            self.isTgtLoadDone = true
            break
        end
        print("koko - 等待 baseParams / sceneParams Json 加载")
        coroutine.yield(Yielders.EndOfFrame)
    end 
    if self.isTgtLoadDone ~= true then 
        printError("koko - 始终没等到 baseParams or sceneParams Json 加载完成")
        return
    end 
    ---
    local jsonString = tostring(self.baseParamsJsonLoader.ResultObject)
    -- 原始数据尾端有杂余信息, 比如: "{}: 408484", 需要剥离大括号后面的那些;
    jsonString = IdolLive3D_Utils.StripTail(jsonString)

    self.baseJson = IdolLive3D_BaseParamsJsonData.New( table.deserialize(jsonString) ) -- rapidjson.decode()

    ------
    self.sceneParamsJsonData = nil
    if isNotNull(self.sceneParamsJsonLoader) then -- 允许不存在
        local sceneJsonString = tostring(self.sceneParamsJsonLoader.ResultObject)
        -- 原始数据尾端有杂余信息, 比如: "{}: 408484", 需要剥离大括号后面的那些;
        sceneJsonString = IdolLive3D_Utils.StripTail(sceneJsonString)
        self.sceneParamsJsonData = table.deserialize(sceneJsonString) -- rapidjson.decode()   
    end 
end


-- 检查 json 数据, 加载 第二批次资源:
---@return boolean
function IdolLive3D_LoaderV1:CheckSourceAndLoadSecondBatchAsync()
    -- 立刻检测:
    
    -- 检测 role animator controller path 是否存在:
    local animatorControllerPath = self.baseJson.data.roleAnimatorControllerPath
    if type(animatorControllerPath)~="string" or (#animatorControllerPath == 0) then 
        printError("json 数据 roleAnimatorControllerPath 为空")
        return false
    end

    -- 加载 角色 animator controller prefab: 
    self.loaders["roleAnimatorController"] = ResourceModule.LoadBundleAsync(animatorControllerPath, nil, true)

    -- 加载 timelines prefab:
    local timelineInfos = self.baseJson.data.timelineInteractiveStates
    for i=1, table.count(timelineInfos) do
        local name = timelineInfos[i].name 
        local path = timelineInfos[i].timelinePath 
        self.loaders[name] = ResourceModule.LoadBundleAsync(path, nil, true) 
    end

    -- 加载 super timelines prefab:
    local superTimelineInfos = self.baseJson.data.superTimelineInteractiveStates
    for i=1, table.count(superTimelineInfos) do
        local superTL = superTimelineInfos[i]
        local superTLName = superTL.name 
        for j=1, table.count(superTL.clips) do
            local clip = superTL.clips[j]
            local name = tostring( "super." .. superTLName .. "." .. clip.clipId ) -- "super.interact_1001.1"
            local path = clip.timelinePath
            self.loaders[name] = ResourceModule.LoadBundleAsync(path, nil, true) 
        end
    end


    -- 加载 simple iStates fx prefab:
    local simpleIStateInfos = self.baseJson.data.simpleInteractiveStates
    for i=1, table.count(simpleIStateInfos) do
        local iState = simpleIStateInfos[i]
        if string.isEmpty(iState.fxPrefabPath) == false then 
            --printError( "load simple fx " .. tostring(iState.name ) )
            local name = iState.name 
            local path = iState.fxPrefabPath
            self.loaders[name] = ResourceModule.LoadBundleAsync(path, nil, true) 
        end
    end


    -- 加载 资源:fullScreenFXs:
    local resources = self.baseJson.data.oths.resources
    local fullScreenFXs = resources.fullScreenFXs

    for i=1, table.count(fullScreenFXs) do
        local fullScreenFX = fullScreenFXs[i]
        if IdolLive3D_Utils.IsKeyValid(fullScreenFX.key) then 
            local key = tostring(fullScreenFX.key)
            self.loaders["opFX_"..key] = ResourceModule.LoadBundleAsync(fullScreenFX.opPrefabPath, nil, true)
            self.loaders["edFX_"..key] = ResourceModule.LoadBundleAsync(fullScreenFX.edPrefabPath, nil, true)
        else 
            printError( "某个 fullScreenFX key 非法: " .. tostring(fullScreenFX.key) )
        end 
    end

    for i=1, table.count(resources.prefabs) do
        local pb = resources.prefabs[i]
        if IdolLive3D_Utils.IsKeyValid(pb.key) then 
            local key = tostring(pb.key)
            self.loaders["prefab_"..key] = ResourceModule.LoadBundleAsync(pb.prefabPath, nil, true)
        else 
            printError( "某个 prefabs key 非法: " .. tostring(pb.key) )
        end 
    end

    -- 加载 资源:materials:
    local materials = resources.materials
    for i=1, table.count(materials) do
        local mat = materials[i]
        if IdolLive3D_Utils.IsKeyValid(mat.key) then 
            local key = tostring(mat.key)
            self.loaders["mat_"..key] = ResourceModule.LoadBundleAsync(mat.matPath, nil, true)
        else 
            printError( "某个 material key 非法: " .. tostring(mat.key) )
        end 
    end

    return true
end



function IdolLive3D_LoaderV1:IsAllLoadingFinished()
    for name,loader in pairs(self.loaders) do 
        if loader.IsSuccess == false then 
            return false 
        end 
    end 
    return true
end


function IdolLive3D_LoaderV1:ReleaseAllLoader()
    for _,loader in pairs(self.loaders) do
        loader:Release()
    end
    self.loaders = {}
    ---
    if isNotNull(self.baseParamsJsonLoader) then 
        self.baseParamsJsonLoader:Release()
        self.baseParamsJsonLoader = nil
    end 
end


-- 等待 第二批 资源 下载完成, 并作设置:
function IdolLive3D_LoaderV1:WaitSecondBatchLoadingAndSetting( isSmlPackage_, isLockFreeCamera_, isDemo_ )
    -- 等待加载完成:

    self.isTgtLoadDone = false
    for i=1,IdolLive3D_States.loadWaitFrames do 
        if self:IsAllLoadingFinished() == true then 
            self.isTgtLoadDone = true
            break
        end 
        print("koko - 等待 第二波资源 加载")
        coroutine.yield(Yielders.EndOfFrame)
    end 
    if self.isTgtLoadDone ~= true then 
        printError("koko - 始终没等到 第二波资源加载完成")
        return
    end 

    ---
    local roleRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Role_")
    local runtimeRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Runtime_")
    local buildsRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Builds_")
    if isNull(roleRootTF) or isNull(runtimeRootTF) or isNull(buildsRootTF) then 
        printError("koko - 爱豆场景内缺少节点: _Role_ 或 _Runtime_ 或 _Builds_")
        return
    end 
    
    --- ===== 装配 资源:fullScreenFXs: =====

    -- 公共资源容器:
    self.allResources = {
        fullScreenFXEnvs = {},
        prefabGOs = {},
        materials = {},
    }
    self:_PrepareFullScreenFXEnvs(  self.baseJson.data.oths.resources.fullScreenFXs,    self.allResources.fullScreenFXEnvs )
    self:_PreparePrefabs(           self.baseJson.data.oths.resources.prefabs,          self.allResources.prefabGOs )
    self:_PrepareMaterials(         self.baseJson.data.oths.resources.materials,        self.allResources.materials        )


    --- ===== 加载 皮肤定制 lua 脚本: =====
    local skinLuaPath = self.baseJson.data.oths.luaPath
    if isNotNull(skinLuaPath) and IdolLive3D_Utils.IsKeyValid(skinLuaPath) then 
        local go = GameObject("skinCustomLua")
        local tf = go.transform 
        tf:SetParent( runtimeRootTF )
        local path = "Game.IdolLive3D.Interactive.Customs." .. skinLuaPath
        print( "本皮肤 定制脚本: " .. tostring(path) )
        local luaBehaviour = AddLuaBehaviour(go, path)
        self.baseJson.data.oths.skinLuaEnv = luaBehaviour.Env -- 此脚本会跟着 go 的卸载自动调用 Delete()
    end 

    --- ===== 装配 timeline states: =====
    --- ===== 装配 simple states fx: =====
    local timelineTFMaps = {}
    local superTimelineTFMaps = {}
    local simpleFxTFMaps = {}
    for k,iLoader in pairs(self.loaders) do
        if self:_IsNameBelowToTimelines(k) then 
            local timelineGO = iLoader:Instantiate()
            timelineGO.transform:SetParent( runtimeRootTF )
            timelineGO.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)
            timelineTFMaps[k] = timelineGO.transform
        end 
        
        if self:_IsNameBelowToSimpleIStates(k) then 
            --printError( "simple fx " .. tostring(k) )
            local fxGO = iLoader:Instantiate()
            fxGO.transform:SetParent( runtimeRootTF )
            fxGO.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)
            simpleFxTFMaps[k] = fxGO.transform
        end 
        
        local retTable = {}
        if self:_IsNameBelowToSuperTimelines(k,retTable) then
            local clip = retTable.ret
            local timelineGO = iLoader:Instantiate()
            timelineGO.transform:SetParent( runtimeRootTF )
            timelineGO.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)
            --KTool.SetActive( timelineGO, false ) -- !! tmp
            ---
            superTimelineTFMaps[clip.superTimelineName] = checkTable(superTimelineTFMaps[clip.superTimelineName])
            superTimelineTFMaps[clip.superTimelineName][clip.clipId] = timelineGO.transform
        end 
    end

    
    --- ===== 装配 总处理器: =====
    local runtimeLoader = self.loaders["runtime"]
    if isNotNull(runtimeLoader) and runtimeLoader.IsSuccess==true then 

        local runtimeGO = runtimeLoader:Instantiate()
        runtimeGO.transform:SetParent( runtimeRootTF )
        runtimeGO.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)

        local luaMainTF = runtimeGO.transform:Find("luas/main")
        if isNotNull(luaMainTF) then 
            ---@type IdolLive3D_MainForRuntime
            self.idolLive3D_Main = IdolLive3D_Utils.GetLuaScr(luaMainTF.gameObject, "Game.IdolLive3D.IdolLive3D_MainForRuntime" )
            assert( self.idolLive3D_Main )
        else 
            printError("koko - 没找到 IdolLive3D_MainForRuntime 脚本")
            return
        end

    else 
        printError("koko - runtime prefab 异步加载失败")
        return
    end 

    --- ===== role animator controller: =====
    local animatorController = nil
    local controllerLoader = self.loaders["roleAnimatorController"]
    if isNotNull(controllerLoader) and controllerLoader.IsSuccess==true then 
        animatorController =  controllerLoader.ResultObject
        --animatorController = GameObject.Instantiate( controllerLoader.ResultObject )
    end 
    if isNull(animatorController) then
        printError("koko - role Animator Controller prefab 异步加载失败")
        return
    end 

    --- ===== 装配 角色: =====
    local roleTF = nil
    local roleLoader = self.loaders["role"]
    if isNotNull(roleLoader) and roleLoader.IsSuccess==true then 

        local roleGO = roleLoader:Instantiate()
        roleGO.transform:SetParent( roleRootTF )
        roleGO.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)
        roleTF = roleGO.transform

        controllerLoader:Retain(roleGO) -- !! MUST 防止 roleAnimatorController 被释放

        -- 隐藏 角色 体内 某些节点:
        local lpComps = roleTF:GetComponentsInChildren(typeof(LuaParameters),true) -- 包含自己
        for i=0, lpComps.Length-1 do 
            local lpComp = lpComps[i]

            local isFindKey = LuaParametersReader.IsFindKey( lpComp, "HideInLive3D" ) -- 宽泛的检测, 只要找到这个 key 就算成立, 暂不检查它的 type 和 value
            if isFindKey == true then 
                print("深度互动: role 体内发现 标注要隐藏的节点: " .. tostring(lpComp.name) )
                KTool.SetActive( lpComp.gameObject, false )
            end 
        end

    else 
        printError("koko - role prefab 异步加载失败")
        return
    end 


    -- ===== 装配 场景内建筑: =====
    local buildsLoader = self.loaders["builds"]
    if isNotNull(buildsLoader) and buildsLoader.IsSuccess==true then 

        local buildGO = buildsLoader:Instantiate()
        local buildTF = buildGO.transform;

        --- 配置 主光源 参数:
        local live3DMainLightTF = buildTF:Find("Live3DMainLight")
        if isNotNull(live3DMainLightTF) then 
            local live3DMainLight = KTool.GetComponent(live3DMainLightTF.gameObject, typeof(Light)) -- 场景模型主光源信息携带者
            assert( isNotNull(live3DMainLight) )

            IdolLive3D_Utils.SetMainLight( live3DMainLightTF.rotation, live3DMainLight.color, live3DMainLight.intensity )
            --- 
            CfUtils.SetActive( live3DMainLightTF.gameObject, false ) -- !! MUST
        else 
            printError("场景模型 prefab 内未找到 Live3DMainLight 节点")
        end 


        --- 改写 CameraCustomData:
        local srcCameraTF = buildTF:Find("Camera_OnlyCustomData")
        if isNotNull(srcCameraTF) then 
            IdolLive3D_Utils.CopyCameraCustomData( srcCameraTF )
        end 


        buildGO.transform:SetParent( buildsRootTF )
        buildGO.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)    
    else 
        printError("koko - builds 装配失败")
        return
    end 


    -- ===== 使用皮肤定制的 主光源信息: (选配) =====
    -- !! 必须在上面的 场景默认主光源配置 之后
    if isNotNull(self.sceneParamsJsonData)  then 
        print("本皮肤自带 场景主光源信息")
        IdolLive3D_Utils.SetMainLight( Quaternion.Euler(self.sceneParamsJsonData.rotation), self.sceneParamsJsonData.color, self.sceneParamsJsonData.intensity )
    end 

    --- baseJson 的一些延迟初始化工作:
    self.baseJson:InitAfterSceneLoaded( self.bgm )

    -- ===
    self.idolLive3D_Main:Init( self.skinId, roleTF, runtimeRootTF, timelineTFMaps, superTimelineTFMaps, simpleFxTFMaps, self.allResources, self.baseJson, animatorController, isSmlPackage_, isLockFreeCamera_, isDemo_ )

    -- 开启地面反射:
    IdolLive3D_Utils.SetPlanarReflections( true )
    

end


---------------------------------------------------
function IdolLive3D_LoaderV1:_IsNameBelowToTimelines( name_ ) 
    local timelineInfos = self.baseJson.data.timelineInteractiveStates
    for i=1, table.count(timelineInfos) do
        if name_ == timelineInfos[i].name  then 
            return true
        end
    end
    return false
end


function IdolLive3D_LoaderV1:_IsNameBelowToSimpleIStates( name_ ) 
    local simpleInfos = self.baseJson.data.simpleInteractiveStates
    for i=1, table.count(simpleInfos) do
        if name_ == simpleInfos[i].name  then 
            return true
        end
    end
    return false
end


---@param retTable_ table, retTable_.ret 内放置返回值
function IdolLive3D_LoaderV1:_IsNameBelowToSuperTimelines( name_, retTable_ ) 
    local parts = string.split2(name_, ".")
    if table.count(parts)==3 and parts[1] == "super" then
        retTable_.ret = {
            superTimelineName = tostring(parts[2]),
            clipId = tostring(parts[3]);
        }
        ---
        return true
    end
    return false
end


function IdolLive3D_LoaderV1:_PrepareFullScreenFXEnvs( fullScreenFXsJson_, fullScreenFXEnvs_ )

    --- json 中显式配置的:
    for i=1, table.count(fullScreenFXsJson_) do
        local fullScreenFX = fullScreenFXsJson_[i]
        local key = tostring(fullScreenFX.key)
        local opGO = self.loaders["opFX_"..key]:Instantiate()
        local edGO = self.loaders["edFX_"..key]:Instantiate()
        local fullScreenFXEnv = IdolLive3D_FullScreenFX.New( opGO.transform, edGO.transform, fullScreenFX.color, false )
        fullScreenFXEnvs_[key] = fullScreenFXEnv
    end

    --- 默认的 黑幕:
    do 
        local key = "_FullBlack_"
        assert( isNull( fullScreenFXEnvs_[key] ) ) -- 默认的 黑幕
        local opGO = GameObject("opFX_black") -- 空go, 占位
        local edGO = GameObject("edFX_black") -- 空go, 占位
        local fullScreenFXEnv = IdolLive3D_FullScreenFX.New( opGO.transform, edGO.transform, Color.black, true )
        fullScreenFXEnvs_[key] = fullScreenFXEnv
    end
end


function IdolLive3D_LoaderV1:_PreparePrefabs( prefabsJson_, outTable_ )
    local runtimeRootTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("_Runtime_")
    --- json 中显式配置的:
    for i=1, table.count(prefabsJson_) do
        local pb = prefabsJson_[i]
        local key = tostring(pb.key)
        local newgo = self.loaders["prefab_"..key]:Instantiate()
        newgo.transform:SetParent( runtimeRootTF )
        CfUtils.SetActive( newgo, false )
        outTable_[key] = newgo
    end
end


function IdolLive3D_LoaderV1:_PrepareMaterials( materialsJson_, materialsTable_ )
    --- json 中显式配置的:
    for i=1, table.count(materialsJson_) do
        local mat = materialsJson_[i]
        local key = tostring(mat.key)
        local loader = self.loaders["mat_"..key]
        local mat = GameObject.Instantiate(loader.ResultObject)
        --kkk
        loader:Retain(mat) -- 防止 mat 被释放
        materialsTable_[key] = mat
    end
end



-- ========================= vcam Brain BlendMode ===============================

function IdolLive3D_LoaderV1:_CacheVCamBlendMode()
    local style, time = IdolLive3D_Utils.GetVCamBlendMode()
    self.cachedVCamDefaultBlendStyle = style
    self.cachedVCamDefaultBlendTime = time
end

function IdolLive3D_LoaderV1:_ResetVCamBlendMode()
    IdolLive3D_Utils.SetVCamBlendMode( self.cachedVCamDefaultBlendStyle, self.cachedVCamDefaultBlendTime )
end


