-- ==============================================
-- 专门给 主游戏 使用的入口函数,  外部不需要 yield, 本函数体内自己维护一个 黑屏淡入淡出
---@param skinId_ number @ 
---@param isDemo_ boolean @ 是否进入试玩模式,  demo 无法破解和谐
function IdolLive3D_LoaderV1.TryOpenScene( skinId_, isDemo_ )
    if type(isDemo_) ~= "boolean" then 
        isDemo_ = false
    end
    ---
    if (isDemo_ == false) and (IdolLive3D_Utils.IsBuyThisSkinsLive3D(skinId_) == false) then 
        local goodsVo = IdolLive3D_Utils.GetLive3dGoodsVo(skinId_)
        GameUtils.Toast( localize("拥有互动情景\"_name_\"后才能继续深入互动",{_name_=goodsVo.name}) ) -- 飘字
        return
    end 
    ---
    local idolLive3D_Loader, baseParamsJsonFilePath, sceneParamsJsonFilePath, live3DCardVoRow = IdolLive3D_LoaderV1._BeforeLoad( skinId_, isDemo_ )
    if idolLive3D_Loader == nil then 
        return
    end 

    xRecord.record('3-025', string.format('deep_inter_%d', checkInt(skinId_)) )

    IdolLive3D_Utils.StopCoroutine( global_co_1 )
    global_co_1 = cs_coroutine.start(function()
        idolLive3D_Loader:_YieldLoad( skinId_, baseParamsJsonFilePath, sceneParamsJsonFilePath, live3DCardVoRow, false, false, isDemo_ )
    end)
end



-- ==============================================
-- 专门给 二段包 使用的入口函数, 外部需要 yield 等待本函数结束
---@param skinId_ number 
---@param isLockFreeCamera_ boolean @ 直接切入近景, 且锁 free camera
function IdolLive3D_LoaderV1.TryOpenSceneFromSmlPackage( skinId_, isLockFreeCamera_ )
    if type(isLockFreeCamera_) ~= "boolean" then 
        isLockFreeCamera_ = false
    end 
    local idolLive3D_Loader, baseParamsJsonFilePath, sceneParamsJsonFilePath, live3DCardVoRow = IdolLive3D_LoaderV1._BeforeLoad( skinId_, false )
    if idolLive3D_Loader == nil then 
        return
    end 
    
    cs_coroutine.yield_return( idolLive3D_Loader:_YieldLoad( skinId_, baseParamsJsonFilePath, sceneParamsJsonFilePath, live3DCardVoRow, true, isLockFreeCamera_, false ) )
end




function IdolLive3D_LoaderV1._BeforeLoad( skinId_, isDemo_ )
    if checkNumber(KCookie.Get(Constants.IsOpnePageing)) == 1 then
        return nil, nil, nil, nil
    end

    --- 检查参数:
    if type(skinId_) ~= "number" then 
        printError(" 参数异常 skinId  = " .. tostring(skinId_)  )
        return nil, nil, nil, nil
    end 
    print(" koko - 爱豆深度交互 skinId  = " .. tostring(skinId_)  )

    --- 读取配表 Live3DCardVo:
    local live3DCardVoRow = IdolLive3D_Utils.GetLive3DCardVoRow(skinId_)
    if isNull(live3DCardVoRow) then 
        printError("koko - 没拿到 Live3DCardVo 配表, 这个皮肤是不是不支持 深度互动 ?")
        return nil, nil, nil, nil
    end 

    ---
    local jsonName = isDemo_ and live3DCardVoRow.demoJsonName or live3DCardVoRow.jsonName
    assert( string.isEmpty(jsonName) == false )

    local baseParamsJsonFilePath = "Presets/IdolLive3D/BaseParams/" .. tostring(jsonName) .. ".json"
    local sceneParamsJsonFilePath = nil
    if string.isEmpty(live3DCardVoRow.sceneParamsJsonName) == false then 
        sceneParamsJsonFilePath = "Presets/IdolLive3D/SceneParams/" .. tostring(live3DCardVoRow.sceneParamsJsonName) .. ".json"
    end 

    --- 确认场景 是否已经被加载
    local sceneInstance = sceneManagement:GetSceneInstance(IdolLive3D_Utils.GetIdolLive3DsceneId())
    if isNull(sceneInstance) then 
        printError("koko - 异常: 爱豆3D场景 尚未被加载")
        return nil, nil, nil, nil
    end


    -- 若发现 场景内各节点下还有残留物, 主动将其清空:
    IdolLive3D_Utils.ClearAllSceneNodes( true )

    --- 新建 IdolLive3D_LoaderV1 实例:
    local idolLive3D_Loader = IdolLive3D_LoaderV1.CreateInstance()
    if isNull(idolLive3D_Loader) then 
        return nil, nil, nil, nil
    end 
    idolLive3D_Loader.skinId = skinId_
    idolLive3D_Loader.live3DCardVoRow = live3DCardVoRow


    --- bgm: 
    if string.isEmpty(live3DCardVoRow.sheet) or string.isEmpty(live3DCardVoRow.cueName) then
        print("使用 默认 bgm")
        idolLive3D_Loader.bgm = {
            sheet = "Audio/bgm_universal_sexy",
            cue   = "bgm_universal_sexy"
        }
    else 
        print("使用 配表 bgm")
        idolLive3D_Loader.bgm = {
            sheet = live3DCardVoRow.sheet,
            cue   = live3DCardVoRow.cueName
        }
    end

    ----------------
    KCookie.Set(Constants.IsOpnePageing, 1)
    UIRaycastBlocker:AddCondition("OpenDialogAction")

    ---
    return idolLive3D_Loader, baseParamsJsonFilePath, sceneParamsJsonFilePath, live3DCardVoRow
end



function IdolLive3D_LoaderV1:_YieldLoad( skinId_, baseParamsJsonFilePath, sceneParamsJsonFilePath, live3DCardVoRow, isSmlPackage_, isLockFreeCamera_, isDemo_ )

    xTry(function()
                
        --- 开始加载 第一波 资源:
        self:StartLoadJsonAsync( baseParamsJsonFilePath, sceneParamsJsonFilePath )
        self:StartLoadFirstBatchAsync( live3DCardVoRow, isDemo_ )

        if isSmlPackage_ == false then
            GameUtils.ShowBlack( BlackInDuration )  ------------------------ 黑幕淡入 ----------------------------------
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds( BlackInDuration ))
        end

        self:_CacheVCamBlendMode()  
        IdolLive3D_Utils.SetVCamBlendMode( CinemachineBlendDefinition.Style.Cut, 0 ) -- !!! 为了让 vcam 秒切, 此处必须设为 Cut            

        --- 打断角色语音
        CriWareUtils_.StopAll()
        CriWareUtils_.PlayVoice("Audio/UI_Menu", "empty")

        if self.live3DCardVoRow.bgmType == 1 then
            --- bgm 走脚本定制, 此时不播放:
        else
            --- bgm 走配表:
            CriWareUtils_.PlayMusic( self.bgm.sheet, self.bgm.cue )
        end
        

        sceneManagement:SetActive(IdolLive3D_Utils.GetIdolLive3DsceneId(), true) -- 激活 爱豆 场景
        
        --- 等待 json 文件被加载完毕
        cs_coroutine.yield_return( self:WaitJsonLoadingFinish() )


        if isSmlPackage_ == false then

            IdolLive3D_States.isUIMainInited = false 

            CS.UINavigationBarRoot.Instance:SetActive(true)
            -- 切换 ui 界面
            --coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.IdolLive3D_MainUI, parameters = nil }, { { id = Constants.UITypeIds.UIHomeView } } ))  -- 会等掉很多帧,
            UIModule.OpenDialog({ id = Constants.UITypeIds.IdolLive3D_MainUI, parameters = { 
                skinId = skinId_,
                baseJson = self.baseJson,
                isDemo = isDemo_,
            } }, UICommonUtils.GetShowDialogArguments() )

            Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false }) -- 把主场景内容关掉了, 降低渲染
        end



        -- 万一 json 文件都没加载出来, 下面的资源加载就不用进行了:
        if self.isTgtLoadDone == true then
            --- 开始加载基于 json文件的 第二波资源:
            local isJsonDataLegal = self:CheckSourceAndLoadSecondBatchAsync()
            if isJsonDataLegal then 

                if isSmlPackage_ == false then
                
                    -- 确保 IdolLive3D_UIMain 一定被初始化完毕了, 否则时序会乱掉:
                    for i=1, 500 do 
                        if IdolLive3D_States.isUIMainInited == true then 
                            break
                        end 
                        --printError("等待一帧")
                        coroutine.yield(Yielders.EndOfFrame)
                    end 

                end

                --- 等待所有资源被加载完毕, 并设置
                cs_coroutine.yield_return( self:WaitSecondBatchLoadingAndSetting(isSmlPackage_, isLockFreeCamera_, isDemo_) )

                self:ReleaseAllLoader()

            else 
                printError("koko - 无法加载后续资源了")
            end
        end
        ---
        if isSmlPackage_ == false then

            --- 等待 几帧, 把一些过场漏洞遮掉:
            coroutine.yield(Yielders.EndOfFrame)
            coroutine.yield(Yielders.EndOfFrame)
            coroutine.yield(Yielders.EndOfFrame)
            coroutine.yield(Yielders.EndOfFrame)
            coroutine.yield(Yielders.EndOfFrame)

            GameUtils.HideBlack( BlackOutDuration ) ------------------------- 黑幕淡出 ---------------------------------
        end
        
        UIRaycastBlocker:RemoveCondition("OpenDialogAction")
        KCookie.Set(Constants.IsOpnePageing, 0)
        ----------

    end, 
    function()

        if isSmlPackage_ == false then
            GameUtils.HideBlack( 0 ) ------------------------- 黑幕淡出 ---------------------------------
        end

        UIRaycastBlocker:RemoveCondition("OpenDialogAction")
        KCookie.Set(Constants.IsOpnePageing, 0)
        printError("%s", debug.traceback())
    end)


end







return IdolLive3D_LoaderV1

